import {preloadCharacters,resetCharacter} from './characters-v5.mjs';
import {newGame,HEROES,totalAtk,totalSpd,totalBp,skills,startBattle,tick,action,reward,enhance,rest,choose,serialize,restore} from './core.mjs';
import {World} from './world.mjs';
import {createModelViewer} from './actors.mjs';
const ART={vampire:'art-02/lucien.png',wolf:'art-02/wolf.png',human:'art-02/eda.png',archivist:'art-02/orin.png'};
let disposeModelViewer=null;
const speakerId=name=>name.includes('리시엔')?'vampire':name.includes('볼프')?'wolf':name.includes('에다')?'human':'archivist';
const speakerRole={vampire:'베르몽 궁정 · 혈월의 귀족',wolf:'아이젠볼프 군단 · 강철의 장교',human:'루멘 자유도시 · 룬 기공사',archivist:'회색종 마을 · 기록관'};
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=newGame(),world,portraits={},keys=new Set(),dialogue=null,toastTimer,nearby=null,profileIndex=0,modalKind=null,frame=0,delay=0,audioOn=false,audioContext=null,checkpoint=null;
const visualVitals={};
const captureVitals=()=>Object.fromEntries([...state.party,...state.enemies].map(h=>[h.id,{hp:h.hp,bp:h.bp,mp:h.mp}]));
const displayed=h=>visualVitals[h.id]?{...h,...visualVitals[h.id]}:h;
const SAVE_KEY='nocturne-three-covenants-v1';
const lore=[
 {title:'베르몽 궁정 · 뱀파이어',sub:'혈정석 / 금융 / 궁정 외교',body:'프랑스와 영국의 중세 귀족에서 영감을 받은 밤의 궁정. 와인색 벨벳, 창백한 금발, 레이스와 가문의 인장이 특징이다. 정제한 혈정석으로 피에 대한 갈증을 억제한다. 긴 수명 덕분에 채권과 외교를 지배하지만, 광석은 철랑의 광산에서, 정제 기술은 인간의 도시에서 빌려야 한다.'},
 {title:'아이젠볼프 군단 · 늑대인간',sub:'광산 / 군사력 / 수송로',body:'회색 장교복, 견장, 가죽 장구류와 강철 대검을 갖춘 군사 국가. 실제 역사적 상징 대신 가상의 철랑 문장을 쓴다. 월광병을 억제하는 혈정석과 인간의 마도 장비가 필요하다. 광산을 지킨다는 명분으로 노동자를 통제하며, 명령과 동료에 대한 책임이 군단 안에서 충돌한다.'},
 {title:'루멘 자유도시 · 인간',sub:'룬 공학 / 정제 기술 / 도시 동력',body:'중세 길드 도시의 수차, 황동 기어, 연금술과 주문 회로가 공존한다. 뱀파이어의 자본과 늑대인간의 광석을 받아 동력 장치를 만든다. 도시 의회는 기술 중립을 내세우지만, 독점 특허와 비밀 계약으로 분쟁에서 이익을 얻는다.'}
];
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function beep(freq=380,duration=.08){if(!audioOn)return;try{audioContext??=new AudioContext();audioContext.resume();const o=audioContext.createOscillator(),gain=audioContext.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audioContext.currentTime);gain.gain.setValueAtTime(.055,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+duration);o.connect(gain).connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+duration);}catch{}}
function renderParty(){const html=state.party.map(displayed).map((h,i)=>`<button class="party-card ${state.active===i?'active':''} ${h.hp<=0?'dead':''}" data-profile="${i}" aria-label="${h.name} 능력치와 장비 보기"><div class="portrait" style="--tint:${h.color}"><img src="${portraits[h.id]||''}" alt="${h.race} ${h.name}"></div><div class="party-info"><div class="name-row"><span>${h.name}</span><small>Lv. ${h.level}</small></div><div class="stat-row"><span>HP</span><span>${Math.ceil(h.hp)} / ${h.maxHp}</span></div><div class="bar hp"><i style="width:${h.hp/h.maxHp*100}%"></i></div><div class="stat-row"><span>BP ${Math.ceil(h.bp)}</span><span>MP ${h.mp}</span></div><div class="bar bp"><i style="width:${h.bp/totalBp(h)*100}%"></i></div><div class="bar mp"><i style="width:${h.mp/h.maxMp*100}%"></i></div></div></button>`).join('');setHTML('#party',html);$('#resources').textContent=`◈ ${state.gold} 은화 · ✧ ${state.shards}`;$('#camp').disabled=state.phase!=='explore'||!!world?.performance.busy;$('#save').disabled=state.phase!=='explore';}
function renderQuest(){const quests=[['침묵한 동력로','서로를 의심하는 세 종족.<br>광장의 기록관에게 사건을 물어보자.','기록관에게 이동'],['공동 조사의 시작','지원을 결정했다.<br>성문 앞의 동력로를 조사하자.','동력로에 접근'],['재의 종지기','장비를 정비한 후 동력로의<br>핵심부에 들어가 진실을 확인하자.','핵심부에 접근'],['세 개의 서약','봉인은 지켜졌다. 하지만<br>운전 기록의 마지막 장이 사라졌다.','결말 다시 보기']];const q=quests[state.chapter];$('#quest-title').textContent=q[0];$('#quest-text').innerHTML=q[1];$('#objective').innerHTML=q[2]+'<span>↗</span>';$('#objective').disabled=state.phase!=='explore';$('#mode').innerHTML=(state.phase==='battle'||world?.performance.busy)?'ENCOUNTER <i></i> 반실시간 전투':'EXPLORATION <i></i> 자유 탐색';}
function renderBattle(){const battle=state.phase==='battle'||!!world?.performance.busy;$('#timeline').hidden=!battle;$('#targets').hidden=!battle;$('#actions').hidden=!(battle&&state.active!==null&&!world?.performance.busy);if(!battle){setHTML('#targets','');return;}$('#battle-status').textContent=world?.performance.busy?'행동 재생 중':state.active!==null?'명령 선택 · 시간 정지':'시간 진행 중';$('#gauge-track').innerHTML=[...state.party,...state.enemies].filter(h=>h.hp>0).map(h=>`<span class="gauge-token ${h.id.startsWith('e')?'foe':''}" title="${h.name}" style="left:${Math.min(100,h.ap)}%">${h.sigil}</span>`).join('');setHTML('#targets',state.enemies.map(displayed).map((e,i)=>e.hp>0?`<button data-target="${i}" class="${state.target===i?'selected':''}" aria-label="${e.name} 선택">${state.target===i?'◇ ':''}${e.name}<div class="bar hp"><i style="width:${e.hp/e.maxHp*100}%"></i></div><div class="target-stats">HP ${e.hp} · BP ${Math.ceil(e.bp)}</div><div class="bar bp"><i style="width:${e.bp/e.maxBp*100}%"></i></div></button>`:'').join(''));
 if(state.active!==null){const h=state.party[state.active],list=skills(h);setHTML('#actions',`<div class="action-title"><span>${h.name}의 차례</span><small>대상을 선택한 뒤 행동하세요 · 숫자 1~5</small></div><div class="action-buttons">${list.map((sk,i)=>`<button data-action="${sk.id}" title="${sk.tip}" ${h.mp<sk.cost||(sk.id==='potion'&&state.potions<1)?'disabled':''}><span>${i+1} ${sk.name}</span><small>${sk.id==='potion'?state.potions+'개 보유':sk.cost?'MP '+sk.cost:sk.id==='attack'?'MP +3':'BP +15'}</small></button>`).join('')}</div><div class="action-tip">${list[1].tip} &nbsp; · &nbsp; 방어로 배리어를 보충할 수 있습니다.</div>`);}}
const htmlCache=new WeakMap();
function setHTML(selector,html){const node=$(selector);if(htmlCache.get(node)!==html){node.innerHTML=html;htmlCache.set(node,html);}}
function refresh(){renderParty();renderQuest();renderBattle();}
function floatText(target,text,cls=''){const p=world.actorPoint(target),el=document.createElement('span');el.className='float '+cls;el.textContent=text;el.style.left=p.x+'px';el.style.top=p.y+'px';$('#floats').append(el);setTimeout(()=>el.remove(),1250);}
function processEvents(events,actorHint=null,kind='attack',before={}){
 for(const e of events)if((e.type==='hit'||e.type==='heal')&&before[e.target])visualVitals[e.target]=before[e.target];
 const hits=events.filter(e=>e.type==='hit'),heals=events.filter(e=>e.type==='heal'),actors=[...new Set(hits.map(e=>e.actor))];if(actorHint&&!actors.includes(actorHint))actors.push(actorHint);
 const finish=()=>{if(events.some(e=>e.type==='victory'))showVictory();if(events.some(e=>e.type==='defeat'))showDefeat();};
 if(!actors.length){if(events.some(e=>e.type==='ready'))beep(760,.06);finish();return;}
 actors.forEach((actor,i)=>{const ownHits=hits.filter(e=>e.actor===actor),ownHeals=i===0?heals:[],targets=ownHits.map(e=>e.target);
  world.performance.enqueue(actor,targets,actor===actorHint?kind:'attack',()=>{for(const e of ownHits){delete visualVitals[e.target];const entity=state.party.find(h=>h.id===e.target)||state.enemies.find(h=>h.id===e.target),g=world.actors[e.target];if(g)g.userData.presentationDead=entity?.hp<=0;floatText(e.target,e.hp?`−${e.hp}`:`−${e.bp} BP`,e.hp?'':'blue');if(e.broken)floatText(e.target,'BREAK','blue');beep(e.hp?190:430);}for(const e of ownHeals){delete visualVitals[e.target];floatText(e.target,e.text,'green');const g=world.actors[e.target];if(g?.userData.presentationDead){g.userData.presentationDead=false;if(g.userData.edition===5)resetCharacter(g);}world.impact(e.target,true);beep(620,.15);}refresh();},i===actors.length-1?finish:null);
 });
}
function doAction(id){if(dialogue||$('#modal').open||delay>0||world.performance.busy)return;const actor=state.party[state.active]?.id,before=captureVitals();const result=action(state,id);if(!result.ok){toast(result.reason);return;}processEvents(result.events,actor,id,before);if(state.enemies[state.target]?.hp<=0)state.target=Math.max(0,state.enemies.findIndex(e=>e.hp>0));refresh();}

function beginBattle(number){checkpoint=serialize({...state,phase:'explore'});closeDialogue();world.setBattle([]);startBattle(state,number);world.setBattle(state.enemies);nearby=null;$('#interact').hidden=true;refresh();toast(number===1?'조우! 명령을 고르는 동안 시간은 멈춥니다.':'재의 종지기 · 먼저 배리어를 무너뜨리세요.');}
function openDialogue(pages,onEnd){dialogue={pages,index:0,onEnd};keys.clear();world.path=[];$('#actions').hidden=true;$('#interact').hidden=true;renderDialogue();}
function renderDialogue(){const d=dialogue.pages[dialogue.index],id=speakerId(d.name);$('#dialogue').hidden=false;$('#dialogue').dataset.speaker=id;$('#dialogue').innerHTML=`<div class="dialogue-portrait"><img src="${portraits[id]}" alt="${d.name} 대화 초상화"><div class="portrait-name">${d.name.split(' · ')[0]}</div></div><div class="dialogue-copy"><div class="speaker">${d.name}</div><span class="dialogue-index">${dialogue.index+1} / ${dialogue.pages.length}</span><div class="speaker-role">${speakerRole[id]}</div><div class="dialogue-body">${d.text}</div><div class="dialogue-bottom">${d.choices?d.choices.map(c=>`<button data-choice="${c.id}">${c.text}<small>${c.effect}</small></button>`).join(''):`<button id="next-dialogue">${dialogue.index===dialogue.pages.length-1?'계속하기':'다음'} &nbsp; ›</button>`}</div></div>`;}
function nextDialogue(){if(!dialogue)return;if(dialogue.pages[dialogue.index].choices)return;if(dialogue.index<dialogue.pages.length-1){dialogue.index++;renderDialogue();}else{const fn=dialogue.onEnd;closeDialogue();fn?.();}}
function closeDialogue(){dialogue=null;$('#dialogue').hidden=true;refresh();}
function intro(){if(state.chapter!==0){openDialogue([{name:'기록관 오린',text:state.chapter===1?'서약은 말보다 행동으로 증명하는 법이지. 북쪽 성문 앞에서 동력로를 조사해 주게.':state.chapter===2?'겉의 파수기만 멎었을 뿐, 핵심부에서는 여전히 종이 울리네. 대장간에서 장비를 정비하고 들어가게.':'기록을 함께 공개하겠다고? 쉬운 길은 아닐 게야. 그래도 오늘은 셋이 같은 길을 골랐군.'}]);return;}
 openDialogue([{name:'기록관 오린',text:'해 질 녘 종이 멎었다네. 혈정석 동력로도, 마을의 수차도 함께. 궁정은 군단을, 군단은 기공사를 범인이라 부르지.'},{name:'리시엔 · 혈월의 귀족',text:'혈정석은 우리 가문의 재산입니다. 손대기 전에 장부부터 확인하시죠. …실종된 광부의 이름도, 그 장부에 있습니까?'},{name:'볼프 · 철랑의 장교',text:'장부를 기다릴 시간은 없다. 봉쇄선을 세우겠다. 하지만 안에 사람이 남아 있다면, 명령보다 구조가 먼저다.'},{name:'에다 · 룬 기공사',text:'고장 난 게 아니에요. 누군가 안전장치를 거꾸로 돌렸어요. 먼저 누구의 지원을 받을지 결정해요.',choices:[{id:'human',text:'주민을 먼저 대피시킨다',effect:'인간 신뢰 +1 · 회복약 +2'},{id:'wolf',text:'군단과 방호선을 세운다',effect:'늑대인간 신뢰 +1 · 전원 BP +8'},{id:'vampire',text:'귀족의 계약을 조사한다',effect:'뱀파이어 신뢰 +1 · 은화 +60'}]}]);}
function reactor(){if(state.chapter===0){toast('먼저 광장의 기록관과 이야기해 주세요.');return;}if(state.chapter===1)openDialogue([{name:'에다',text:'혈정석이 역류하고 있어요. 저 파수기는 우리를 침입자로 인식할 거예요!'},{name:'볼프',text:'내가 배리어를 부수겠다. 리시엔은 관통 공격, 에다는 수복을 맡아라. 누가 먼저 쓰러질지는 서약서에 없으니까.'}],()=>beginBattle(1));else if(state.chapter===2)openDialogue([{name:'리시엔',text:'이 안쪽의 봉인… 우리 가문의 인장이군요. 하지만 군단의 수송 코드와 인간의 특허 번호도 함께 있습니다.'},{name:'에다',text:'세 종족이 모두 알고 있었던 거예요. 동력로는 발전기가 아니라, 아래에서 깨어나는 무언가를 재우는 장치였어요.'},{name:'볼프',text:'보고서는 살아 돌아가서 쓰자. 지금은 종부터 멈춘다.'}],()=>beginBattle(2));else showEnding();}
function interact(){if(state.phase!=='explore'||dialogue||$('#modal').open||world.performance.busy)return;if(!nearby){toast('기록관, 대장간 또는 동력로 가까이에서 상호작용하세요.');return;}beep();if(nearby.id==='archivist')intro();if(nearby.id==='forge')openMenu('party');if(nearby.id==='gate')reactor();}
function updateLabels(){if(!world)return;const battle=state.phase==='battle';let html='';if(!battle)for(const p of world.landmarks){const screen=world.project(p.x,p.id==='gate'?2.8:2.2,p.z);html+=`<div class="world-label" style="left:${screen.x}px;top:${screen.y}px"><b>${p.id==='archivist'&&state.chapter===0?'!':p.id==='forge'?'⚒':'◇'}</b>${p.name}</div>`;}for(const h of state.party){if(h.hp<=0)continue;const p=world.actorPoint(h.id);html+=`<div class="world-label pawn" style="left:${p.x}px;top:${p.y}px">${h.name}</div>`;}$('#labels').innerHTML=html;
 if(!battle&&!dialogue&&!$('#modal').open){const p=world.actors.vampire.position;nearby=world.landmarks.find(l=>Math.hypot(l.x-p.x,l.z-p.z)<2.65);$('#interact').hidden=!nearby;if(nearby)$('#interact-button').innerHTML=`<kbd>E</kbd> ${nearby.id==='archivist'?'기록관과 대화':nearby.id==='forge'?'장비 정비하기':state.chapter===3?'결말 다시 보기':'동력로 조사하기'}`;}else $('#interact').hidden=true;}
function saveGame(silent=false){if(state.phase!=='explore')return false;try{localStorage.setItem(SAVE_KEY,serialize(state));if(!silent)toast('이 브라우저에 여정을 저장했습니다.');return true;}catch{if(!silent)toast('브라우저가 저장을 허용하지 않습니다.');return false;}}
function showVictory(){if(state.phase!=='victory')return;const boss=state.battle===2;reward(state);world.clearEnemies();refresh();saveGame(true);if(boss){openDialogue([{name:'에다',text:'종이 멎었어요. 원본 기록을 보세요. 궁정은 자금을, 군단은 광석을, 의회는 설계를 댔어요. 누구도 결백하지 않았어요.'},{name:'리시엔',text:'내 가문만 보호하면 사건은 묻힐 겁니다. 그렇다면… 이번에는 가문보다 이 서약을 택하겠습니다.'},{name:'볼프',text:'명령서에는 없던 선택이군. 좋다. 세 사람이 함께 증인이 되자.'}],showEnding);}else{openModal('첫 번째 종이 멎다','VICTORY',`<div class="ending"><small class="money">전투 승리</small><h3>불완전한 동맹</h3><p>서로 다른 세 사람의 힘이 처음으로 맞물렸다.<br>파수기의 잔해 아래에서 핵심부로 향하는 길이 드러났다.</p><p class="money">은화 +120 · 혈정석 +4 · 회복약 +2<br>전원 경험치 +100 · 레벨 상승 · HP·MP 회복</p><button class="primary" id="victory-continue">장비 정비 후 계속하기</button><div class="checkpoint">여정이 이 브라우저에 자동 저장됩니다.</div></div>`);}}
function showDefeat(){if(state.phase!=='defeat')return;openModal('동맹은 아직 끝나지 않았다','DEFEAT',`<div class="ending"><h3>잠시 물러서다</h3><p>배리어를 유지하며 에다의 수복 술식을 사용해 보세요.<br>회복약은 쓰러진 동료도 다시 일으킬 수 있습니다.</p><button class="primary" id="retry">전투 직전으로 돌아가기</button><div class="checkpoint">전투에서 사용한 물자도 복원됩니다.</div></div>`);}
function showEnding(){const line={human:'가장 먼저 구한 것은 마을 사람들이었다. 그들이 이제 세 사람의 증인이 된다.',wolf:'군단이 세운 방호선은 국경 대신 사람을 지켰다. 볼프는 처음으로 그 명령서에 이름을 쓴다.',vampire:'귀족의 장부에서 시작한 조사는 세 국가의 비밀 계약으로 이어졌다. 리시엔은 인장을 꺾는다.'}[state.choice]||'';openModal('제1장 · 재의 종소리','CHAPTER COMPLETE',`<div class="ending"><small class="money">세 개의 서약</small><h3>진실에는 주인이 없다</h3><p>${line}</p><p>세 사람은 원본 기록을 함께 공개하기로 한다.<br>그러나 마지막 장에 적혀 있던 수신인의 이름은 이미 지워져 있었다.</p><p class="muted">제2장 예고 · 피로 쓰인 초대장<br><small>이번 프로토타입은 제1장까지 플레이할 수 있습니다.</small></p><p class="money">보스 보상: 은화 +220 · 혈정석 +6 · 경험치 +150</p><button class="primary" id="ending-explore">마을로 돌아가기</button><button class="primary" id="new-journey">새로운 여정</button></div>`);}
function openModal(title,eyebrow,html){disposeModelViewer?.();disposeModelViewer=null;keys.clear();world.path=[];$('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eyebrow;$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if(state.phase==='defeat')return;$('#modal').close();modalKind=null;keys.clear();}
function openMenu(kind){if(dialogue)return;modalKind=kind;if(kind==='party'){renderProfile();return;}if(kind==='journal'){openModal('여행 수첩','CHRONICLES',`<div class="tabs"><button data-journal="world" class="selected">세계와 인물</button><button data-journal="log">여정 기록</button><button data-journal="design">프로토타입 기획</button></div><div id="journal-page">${worldLore()}</div>`);return;}openModal('여행의 안내','FIELD GUIDE',`<div class="journal-block"><h3>이동과 조사</h3><p>바닥을 클릭하거나 WASD / 방향키로 이동합니다. 기록관, 룬 대장간, 동력로 가까이에서 E를 누르세요. 오른쪽 여정 버튼은 현재 목표 근처까지 자동으로 이동합니다.</p></div><div class="journal-block"><h3>시점과 메뉴</h3><p>Q / R: 시점 회전 · 마우스 휠 또는 ＋ / −: 확대·축소<br>I: 인물·장비 · J: 여행 수첩 · Esc: 메뉴 닫기<br>이름이 적힌 동료 카드를 눌러 장비를 확인할 수도 있습니다.</p></div><div class="journal-block"><h3>반실시간 전투</h3><p>민첩이 높을수록 행동 게이지가 빨리 찹니다. 동료의 차례에는 시간이 멈춥니다. 적 이름을 눌러 대상을 고르고 1~5 또는 행동 버튼을 사용하세요. BP는 배리어, HP는 생명력, MP는 마력입니다.</p></div><div class="journal-block"><h3>동료의 조합</h3><p>리시엔의 혈월 찌르기는 BP를 무시하고 흡혈합니다. 볼프의 강철 파쇄는 배리어를 크게 깎고 파괴 시 적의 행동을 늦춥니다. 에다는 전체 공격과 위급한 동료의 치료·소생을 담당합니다. 기본 공격은 MP를 3 회복합니다.</p></div><div class="journal-block"><h3>성장과 저장</h3><p>승리하면 경험치와 강화 재료를 얻습니다. 인물·장비에서 무기 교체와 +3까지 확정 강화를 할 수 있습니다. 야영은 무료로 전원을 회복합니다. 저장은 현재 브라우저에만 보관되며 전투 승리 후 자동 저장됩니다.</p></div><button class="primary" id="new-journey">새로운 여정 시작</button>`);}
function worldLore(){return lore.map(l=>`<div class="journal-block"><small>${l.sub}</small><h3>${l.title}</h3><p>${l.body}</p></div>`).join('')+`<div class="journal-block"><h3>공동 동력로</h3><p>궁정의 자금, 군단의 광석, 자유도시의 기술. 세 국가는 서로 없이는 유지될 수 없는 동력로를 만들었다. 정작 그것이 무엇을 가두는 장치인지는 마을 사람들에게 알리지 않았다.</p></div>`;}
function designNotes(){return `<div class="journal-block"><h3>악튜러스에서 가져온 설계 원칙</h3><p>일본 발매사 공식 설명에서 반실시간 전투, 명령 입력 중 정지, 민첩 기반 행동 게이지, 장비로 늘리는 BP와 자연 회복을 확인했다. 이를 3인 파티의 관통·파쇄·수복 조합으로 축소했다. 원작의 구체적 수치나 자산을 재현한 것은 아니다.</p><p><a href="https://www.falcom.co.jp/arc/system/" target="_blank" rel="noopener">공식 전투 시스템 설명 ↗</a></p></div><div class="journal-block"><h3>입체적인 세계, 만화 같은 인물</h3><p>원작의 3D 배경과 2D 캐릭터 조합 대신, 배경과 2~3등신 캐릭터 모두를 3D로 제작했다. 정사영 카메라, 단계형 명암, 어두운 외곽선을 사용한다. 얼굴·머리카락·의상·무기를 세분화한 3등신 스킨드 모델과 관절 기반 대기·보행·공격 모션을 적용했다. 대화와 동료 카드에는 별도로 제작한 일러스트 초상화를 사용한다.</p><p><a href="https://games.sina.com.cn/newgames/0203/03158315.shtml" target="_blank" rel="noopener">당시 그래픽 소개 기사 ↗</a></p></div><div class="journal-block"><h3>명확한 이익에서 시작하는 군상극</h3><p>원작의 공식 소개에서 인간의 선악과 황폐해지는 세계 속의 갈등을 참고했다. 본작에서는 종족의 본성을 선악으로 고정하지 않고, 각 국가의 의존 관계와 개인의 선택을 중심에 둔다. 전쟁과 봉인의 진실은 이번 작품의 독자 설정이다.</p><p><a href="https://www.falcom.co.jp/arc/index2.html" target="_blank" rel="noopener">공식 작품 소개 ↗</a></p></div><div class="journal-block"><h3>이번 구현의 범위</h3><p>마을 1곳, 주인공 3명, 대화 선택 3개, 일반 전투와 보스 전투 각 1회, 레벨 성장, 캐릭터별 스킬 2개, 무기 교체, 무기·방어구 +3 강화, 회복약, 야영, 브라우저 저장.</p><p>스킬은 레벨 1부터 공개해 조합을 검증한다. 전투 중 위치 이동, 시전 취소, 장거리 탐험, 스킬 트리, 상점 경제, 음성, 표정별 초상화는 후속 제작 범위다. 친밀도는 첫 선택과 결말 문장에만 반영된다.</p></div><div class="journal-block"><h3>다음 검증 목표</h3><p>세 종족을 섞어 싸울 이유가 충분한지, BP 파괴와 HP 관통 중 무엇을 선택하는지, 전투 사이 정비가 번거롭지 않은지를 먼저 확인한다. 그 결과로 전투 내 이동과 시전 시간을 확장한다.</p></div>`;}
function renderProfile(){const h=state.party[profileIndex],can=state.phase==='explore';const stat=[['생명력',`${h.hp} / ${h.maxHp}`],['배리어',`${Math.ceil(h.bp)} / ${totalBp(h)}`],['마력',`${h.mp} / ${h.maxMp}`],['공격',totalAtk(h)],['마법',h.mag],['방어',h.def],['민첩',totalSpd(h)]];openModal('동행자와 장비','THE THREE COVENANTS',`<div class="tabs">${state.party.map((p,i)=>`<button data-profile-tab="${i}" class="${i===profileIndex?'selected':''}">${p.name} · ${p.race}</button>`).join('')}</div><div class="profile"><div class="profile-art-wrap"><img class="profile-art" src="${portraits[h.id]}" alt="${h.name} 인물 초상화"><span>${h.role}</span></div><div><h3>${h.name} <small>Lv. ${h.level}</small></h3><p class="tags">${h.race} / ${h.role}</p><p class="muted">${h.bio}</p><small class="money">경험치 ${h.xp} / ${h.level*80} · 종족 신뢰 +${state.affinity[h.id]}</small></div></div><div class="model-section"><div id="character-viewer" aria-label="${h.name} 3D 모델. 좌우로 드래그해 회전할 수 있습니다."></div><div class="model-caption"><small>CHARACTER MODEL</small><h3>${h.name}</h3><p>${h.id==='vampire'?'겹친 은발과 날렵한 눈매. 레이스 크라바트, 금실 자수 코트와 바스켓 힐트 레이피어.':h.id==='wolf'?'길어진 주둥이와 층진 회색 갈기. 강철 견갑, 가죽 크로스 벨트와 양날 대검.':'갈색 단발과 황동 고글. 가죽 하네스, 연금술 배낭과 회전 룬 캐스터.'}</p><span>드래그로 회전 · 휠로 확대</span><p><a href="atelier.html" target="_blank" rel="noopener">큰 화면에서 동작 확인 ↗</a></p></div></div><div class="stats-grid">${stat.map(([label,value])=>`<div>${label}<b>${value}</b></div>`).join('')}</div><div class="section-title">장비 정비 <small>◈ ${state.gold} 은화 · ✧ ${state.shards} 혈정석</small></div><div class="equipment"><div>${h.loadout?'중량형 ':''}${h.weapon} <span class="money">+${h.upgrade}</span><small>${h.loadout?'중량형: 공격 +7 / 민첩 −3':'표준형: 균형 잡힌 공격과 민첩'} · 강화 1회당 공격 +4</small></div><button id="switch-weapon" ${can?'':'disabled'}>${h.loadout?'표준형 장착':'중량형 장착'}</button><button data-enhance="weapon" ${can&&h.upgrade<3&&state.gold>=50+h.upgrade*40&&state.shards>=2+h.upgrade?'':'disabled'}>${h.upgrade<3?`강화 · ${50+h.upgrade*40} 은화 / ${2+h.upgrade} 혈정석`:'최대 강화 +3'}</button></div><div class="equipment"><div>${h.armor} <span class="money">+${h.armorUpgrade}</span><small>강화 1회당 최대 배리어 +8 · 실패 없음</small></div><button data-enhance="armor" ${can&&h.armorUpgrade<3&&state.gold>=50+h.armorUpgrade*40&&state.shards>=2+h.armorUpgrade?'':'disabled'}>${h.armorUpgrade<3?`강화 · ${50+h.armorUpgrade*40} 은화 / ${2+h.armorUpgrade} 혈정석`:'최대 강화 +3'}</button></div><div class="section-title">마법과 기술</div>${skills(h).filter(s=>['skill','support'].includes(s.id)).map(s=>`<div class="equipment"><div>${s.name}<small>${s.tip}</small></div><span class="money">MP ${s.cost}</span></div>`).join('')}<p class="checkpoint">장비 교체와 강화는 탐색 중에 가능합니다. 현재 장비 두 종류는 처음부터 보유하고 있습니다.</p>`);disposeModelViewer=createModelViewer($('#character-viewer'),h.id); }
function confirmNew(){openModal('새로운 여정','NEW JOURNEY',`<div class="ending"><p>진행 중인 여정과 이 브라우저의 저장을 지우고<br>첫 장면부터 시작합니다.</p><button class="primary" id="confirm-new">처음부터 시작</button><button class="primary" id="cancel-new">취소</button></div>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.menu)openMenu(d.menu);if(d.profile!==undefined){profileIndex=+d.profile;openMenu('party');}if(d.profileTab!==undefined){profileIndex=+d.profileTab;renderProfile();}if(d.target!==undefined){state.target=+d.target;renderBattle();}if(d.action)doAction(d.action);if(d.enhance){const r=enhance(state,profileIndex,d.enhance);toast(r.ok?'강화 성공! 능력치가 상승했습니다.':r.reason);renderProfile();renderParty();if(r.ok){saveGame(true);beep(900,.12);}}if(d.choice){if(choose(state,d.choice)){closeDialogue();refresh();saveGame(true);toast('서약을 기록했습니다. 북쪽 동력로로 이동하세요.');}}if(d.journal){document.querySelectorAll('[data-journal]').forEach(el=>el.classList.toggle('selected',el===b));$('#journal-page').innerHTML=d.journal==='world'?worldLore():d.journal==='design'?designNotes():`<div class="journal-block"><h3>현재 목표</h3><p>${$('#quest-text').innerHTML}</p></div>${state.log.length?state.log.map(t=>`<p class="muted">◇ ${escape(t)}</p>`).join(''):'<p class="muted">아직 기록된 사건이 없습니다. 기록관과 이야기를 시작하세요.</p>'}`;}
 switch(b.id){case'objective':if(state.chapter===3){showEnding();break;}if(state.chapter===0)world.moveTo(-4.1,.5);else world.moveTo(0,-5.4);break;case'interact-button':interact();break;case'next-dialogue':nextDialogue();break;case'close-modal':closeModal();break;case'rotate-left':world.rotate(-Math.PI/4);break;case'rotate-right':world.rotate(Math.PI/4);break;case'zoom-in':world.setZoom(world.zoom*1.12);break;case'zoom-out':world.setZoom(world.zoom/1.12);break;case'camp':if(rest(state)){refresh();toast('야영을 마쳤습니다. 전원의 생명력·배리어·마력을 회복했습니다.');beep(550,.2);}break;case'save':saveGame();break;case'sound':audioOn=!audioOn;b.textContent=audioOn?'소리 켜짐':'소리 꺼짐';b.setAttribute('aria-label',audioOn?'소리 끄기':'소리 켜기');beep();break;case'switch-weapon':if(state.phase==='explore'){const h=state.party[profileIndex];h.loadout=1-h.loadout;renderProfile();renderParty();saveGame(true);}break;case'victory-continue':profileIndex=0;openMenu('party');break;case'retry':state=restore(checkpoint)||newGame();rest(state);world.clearEnemies();$('#modal').close();refresh();toast('전투 직전으로 돌아왔습니다. 장비를 정비하고 다시 도전하세요.');break;case'ending-explore':closeModal();break;case'new-journey':confirmNew();break;case'cancel-new':closeModal();break;case'confirm-new':state=newGame();world.clearEnemies();world.actors.vampire.position.set(-2,0,3);world.path=[];$('#modal').close();try{localStorage.removeItem(SAVE_KEY);}catch{}refresh();toast('새로운 여정을 시작합니다.');break;case'load-save':{try{const saved=restore(localStorage.getItem(SAVE_KEY));if(saved){state=saved;$('#modal').close();refresh();toast('저장한 여정을 불러왔습니다.');}else toast('저장 기록을 읽을 수 없습니다.');}catch{toast('브라우저 저장에 접근할 수 없습니다.');}}break;case'continue-new':closeModal();break;}
});
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright',' '].includes(k)&&!$('#modal').open)e.preventDefault();if(e.repeat&&['e','q','r','i','j'].includes(k))return;if($('#modal').open){if(k==='escape'&&state.phase==='defeat')e.preventDefault();return;}if(dialogue){if(k==='enter'||k===' '){e.preventDefault();nextDialogue();}return;}keys.add(k);if(k==='e')interact();if(k==='q')world.rotate(-Math.PI/4);if(k==='r')world.rotate(Math.PI/4);if(k==='i')openMenu('party');if(k==='j')openMenu('journal');if(['1','2','3','4','5'].includes(k))doAction(['attack','skill','support','guard','potion'][+k-1]);});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>keys.clear());$('#modal').addEventListener('cancel',e=>{if(state.phase==='defeat')e.preventDefault();});$('#modal').addEventListener('close',()=>{keys.clear();if(!$('#modal').open){disposeModelViewer?.();disposeModelViewer=null;}});
try{await preloadCharacters();world=new World($('#world'),p=>{if(dialogue||$('#modal').open)return;if(p.enemy){if(state.phase==='battle'){state.target=state.enemies.findIndex(e=>e.id===p.enemy);renderBattle();}return;}if(state.phase==='explore'&&!world.moveTo(p.x,p.z))toast('이곳으로는 이동할 수 없습니다. 길을 선택하세요.');});portraits={...ART};Object.values(ART).forEach(src=>{const img=new Image();img.src=src;});refresh();let previous=performance.now();function loop(now){requestAnimationFrame(loop);const dt=Math.min((now-previous)/1000,.05);previous=now;const paused=!!dialogue||$('#modal').open||document.hidden;if(!paused&&delay<=0&&!world.performance.busy){const before=captureVitals(),events=tick(state,dt);if(events.length){processEvents(events,null,'attack',before);refresh();}}delay=Math.max(0,delay-dt);world.update(dt,state,keys,paused);frame++;if(frame%5===0){updateLabels();if(state.phase==='battle'&&!paused)renderBattle();}if(frame%35===0&&state.phase==='battle')renderParty();}requestAnimationFrame(loop);updateLabels();let saved;try{saved=restore(localStorage.getItem(SAVE_KEY));}catch{}if(saved)openModal('기록된 여정','CONTINUE',`<div class="ending"><h3>다시, 회색종 마을로</h3><p>이 브라우저에 저장된 여정이 있습니다.<br>동료 레벨 ${saved.party[0].level} · ${saved.chapter===3?'제1장 완료':'제1장 진행 중'}</p><button class="primary" id="load-save">이어서 하기</button><button class="primary" id="continue-new">처음부터 둘러보기</button></div>`);
 const context=document.modelContext;if(context?.registerTool){const lifetime=new AbortController();window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});try{Promise.resolve(context.registerTool({name:'read_nocturne_journey',description:'Read current chapter, party health and quest in Nocturne without changing the game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input&&Object.keys(input).length)throw Error('No inputs accepted');return {chapter:state.chapter,phase:state.phase,quest:$('#quest-title').textContent,party:state.party.map(h=>({name:h.name,level:h.level,hp:h.hp,bp:Math.ceil(h.bp),mp:h.mp}))};}},{signal:lifetime.signal})).catch(()=>{});}catch{}}
}catch(error){console.error(error);const el=document.createElement('div');el.id='fatal';el.innerHTML='<h2>3D 화면을 시작할 수 없습니다.</h2><p>모델 파일을 불러오지 못했거나 3D 화면을 시작하지 못했습니다. 새로고침한 뒤에도 같다면 네트워크 연결과 브라우저의 하드웨어 가속을 확인해 주세요.</p>';$('#stage').append(el);}
